#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Simple implementation to convert markdown to HTML
    std::string html = markdown;
    // Replace markdown tags with HTML tags
    std::regex markdownPattern(R"(^#\s*([0-9]+)\s*([a-zA-Z]+))");
    std::regex htmlPattern(R"<h1>$2</h1>");
    html = std::regex_replace(html, markdownPattern, htmlPattern);
    return html;
}
```

